"use client";
import { type ReactNode, useState } from "react";
import { cx } from "../../utils/cx";
import { formatNumber } from "./chart-card";
import { ChartPlot } from "./chart-plot";
import {
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  ink,
  PeriodSelect,
  StatTiles,
  safeRatio,
  useChartRange,
} from "./pro-chart";
export interface FunnelStage {
  label: string;
  value: number;
  color?: string;
  icon?: ReactNode;
}
export interface FunnelChartRange extends ChartRange {
  stages: FunnelStage[];
}
export interface FunnelChartCardProps extends ChartCommonProps {
  stages?: FunnelStage[];
  ranges?: FunnelChartRange[];
  shape?: "smooth" | "sharp";
  mono?: boolean;
  tiles?: boolean;
}
export const FUNNEL_STAGES: FunnelStage[] = [
  { label: "Link opened", value: 197 },
  { label: "Started", value: 110 },
  { label: "Completed", value: 77 },
  { label: "Converted", value: 38 },
];
const RANGES: FunnelChartRange[] = [
  { id: "7d", label: "Last 7 days", stages: FUNNEL_STAGES, delta: 0.052 },
  {
    id: "30d",
    label: "Last 30 days",
    stages: FUNNEL_STAGES.map((s, i) => ({
      ...s,
      value: [842, 463, 301, 152][i]!,
    })),
    delta: 0.034,
  },
  {
    id: "90d",
    label: "Last 90 days",
    stages: FUNNEL_STAGES.map((s, i) => ({
      ...s,
      value: [2510, 1380, 902, 455][i]!,
    })),
    delta: -0.018,
  },
];
export function FunnelChartCard({
  stages,
  ranges: supplied,
  title = "Sign-up funnel",
  shape = "smooth",
  mono = false,
  tiles = true,
  ...props
}: FunnelChartCardProps = {}) {
  const ranges = supplied ?? (stages ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    data = period.current?.stages ?? stages ?? FUNNEL_STAGES,
    [active, setActive] = useState<number | null>(null),
    format = props.format ?? formatNumber,
    first = data[0]?.value ?? 0;
  const colors = data.map((s, i) => (mono ? "var(--color-text-tertiary)" : (s.color ?? ink(i))));
  return (
    <ChartFrame
      title={active == null ? title : (data[active]?.label ?? title)}
      value={
        active == null
          ? (period.current?.headline ?? props.headline ?? first)
          : (data[active]?.value ?? 0)
      }
      format={format}
      delta={active == null ? (period.current?.delta ?? props.delta) : undefined}
      animateNumber
      pulseKey={active}
      className={cx("h-[329px]", props.className)}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            setActive(null);
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? "Last 7 days"}
        />
      }
      footer={
        tiles && (
          <StatTiles
            columns={Math.max(1, data.length)}
            responsive
            focusable={false}
            inactiveOpacity={0.5}
            items={data.map((s, i) => ({
              label: s.label,
              value: format(s.value),
              color: colors[i],
              activeColor: s.color ?? (mono ? colors[i] : colors[i]?.replace(")", "-active)")),
            }))}
            active={active}
            onHover={setActive}
          />
        )
      }
    >
      <ChartPlot roundDimensions>
        {({ width, height }) => {
          const count = Math.max(1, data.length),
            gap = 3;
          const column = Math.max(0, (width - gap * (count - 1)) / count);
          const center = height / 2,
            inset = shape === "sharp" ? 0 : 12;
          const heights = data.map((stage) =>
            Math.max(0, safeRatio(stage.value, first) * Math.max(0, height - inset * 2)),
          );
          const path = (index: number, expansion: number) => {
            const x = index * (column + gap),
              right = x + column;
            const h = heights[index] ?? 0,
              next = heights[index + 1] ?? h;
            const top = center - h / 2 - expansion,
              bottom = center + h / 2 + expansion;
            const nextTop = center - next / 2 - expansion,
              nextBottom = center + next / 2 + expansion;
            if (shape === "sharp")
              return `M${x},${top} L${right},${nextTop} L${right},${nextBottom} L${x},${bottom} Z`;
            const plateau = x + column * 0.42,
              control = x + column * 0.71;
            return `M${x},${top} L${plateau},${top} C${control},${top} ${control},${nextTop} ${right},${nextTop} L${right},${nextBottom} C${control},${nextBottom} ${control},${bottom} ${plateau},${bottom} L${x},${bottom} Z`;
          };
          const opacity = (i: number) => (active == null || active === i ? 1 : 0.3);
          return (
            <svg
              width={width}
              height={height}
              viewBox={`0 0 ${width} ${height}`}
              className="absolute inset-0 overflow-visible"
              role="img"
              aria-label={`${title}: ${data.map((s) => `${s.label} ${format(s.value)}`).join(", ")}`}
            >
              {shape !== "sharp" &&
                [
                  [12, 0.1],
                  [6, 0.22],
                ].map(([expansion, alpha]) =>
                  data.map((stage, i) => (
                    <path
                      key={`${expansion}-${stage.label}`}
                      d={path(i, expansion!)}
                      fill={colors[i]}
                      fillOpacity={alpha}
                      opacity={opacity(i)}
                      className="pointer-events-none transition-opacity duration-200 ease-out"
                    />
                  )),
                )}
              {data.map((stage, i) => (
                <path
                  key={stage.label}
                  d={path(i, 0)}
                  fill={
                    active === i
                      ? (stage.color ?? (mono ? colors[i] : colors[i]?.replace(")", "-active)")))
                      : colors[i]
                  }
                  opacity={opacity(i)}
                  onMouseEnter={() => setActive(i)}
                  onMouseLeave={() => setActive(null)}
                  className="cursor-default transition-[fill,opacity] duration-200 ease-out"
                />
              ))}
              {data.map((stage, i) => {
                const label = `${Math.round(safeRatio(stage.value, first) * 100)}%`,
                  badgeWidth = label.length * 7.2 + 16;
                const x = i * (column + gap) + column / 2;
                return (
                  <g
                    key={stage.label}
                    opacity={opacity(i)}
                    onMouseEnter={() => setActive(i)}
                    onMouseLeave={() => setActive(null)}
                    className="cursor-default transition-opacity duration-200 ease-out"
                  >
                    <rect
                      x={x - badgeWidth / 2}
                      y={center - 10}
                      width={badgeWidth}
                      height={20}
                      rx={10}
                      fill="var(--color-background-secondary-default)"
                    />
                    <text
                      x={x}
                      y={center}
                      dy={4}
                      textAnchor="middle"
                      fontSize={12}
                      fontWeight={500}
                      fill="var(--color-text-primary)"
                      className="pointer-events-none tabular-nums"
                    >
                      {label}
                    </text>
                  </g>
                );
              })}
            </svg>
          );
        }}
      </ChartPlot>
    </ChartFrame>
  );
}
